315	\begin{lemma}[Triangle inequality; Fact 4.28 in \cite{Natarajan2018NEEXP}]\label{fact:triangle}
316		\lean{MIPStarRE.QPBT.opFamilyDistSq_le_of_le_of_le}
317		\leanok
318		\uses{def:povm-distance}
319		If $A^x_a \approx_\delta B^x_a$ and $B^x_a \approx_{\eps} C^x_a$, then $A^x_a \approx_{\delta+\eps} C^x_a$.
320	\end{lemma}
321	\begin{proof}
322		\uses{def:povm-distance}
323		Stated in the source without proof; it is Fact 4.28 of \cite{Natarajan2018NEEXP}. For every $x$ and $a$, $\lVert (A^x_a - C^x_a)\ket{\psi} \rVert^2 \le 2\lVert (A^x_a - B^x_a)\ket{\psi} \rVert^2 + 2\lVert (B^x_a - C^x_a)\ket{\psi} \rVert^2$. Averaging over $x$ and summing over $a$ gives the claim; the factor $2$ is absorbed by the $O(\cdot)$ in Definition~\ref{def:povm-distance}.
324	\end{proof}
